INSERT INTO `Template` VALUES ('beta-signup','Product Beta Signup','Collect signups for your product beta program','product','{\"fields\":[{\"id\":\"fullName\",\"type\":\"text\",\"label\":\"Full Name\",\"required\":true,\"placeholder\":\"Your name\"},{\"id\":\"email\",\"type\":\"email\",\"label\":\"Email Address\",\"required\":true,\"placeholder\":\"your@email.com\"},{\"id\":\"company\",\"type\":\"text\",\"label\":\"Company\",\"required\":false,\"placeholder\":\"Company name\"},{\"id\":\"role\",\"type\":\"select\",\"label\":\"Your Role\",\"required\":true,\"options\":[{\"label\":\"Developer\",\"value\":\"developer\"},{\"label\":\"Designer\",\"value\":\"designer\"},{\"label\":\"Product Manager\",\"value\":\"pm\"},{\"label\":\"Executive\",\"value\":\"executive\"},{\"label\":\"Other\",\"value\":\"other\"}]},{\"id\":\"problem\",\"type\":\"textarea\",\"label\":\"What problem would this solve for you?\",\"required\":true,\"placeholder\":\"Describe your use case...\"},{\"id\":\"budget\",\"type\":\"select\",\"label\":\"Budget Range\",\"required\":false,\"options\":[{\"label\":\"Free tier only\",\"value\":\"free\"},{\"label\":\"$1-50/month\",\"value\":\"starter\"},{\"label\":\"$51-200/month\",\"value\":\"pro\"},{\"label\":\"$200+/month\",\"value\":\"enterprise\"}]},{\"id\":\"contact\",\"type\":\"radio\",\"label\":\"Preferred Contact Method\",\"required\":true,\"options\":[{\"label\":\"Email\",\"value\":\"email\"},{\"label\":\"Phone\",\"value\":\"phone\"},{\"label\":\"Slack\",\"value\":\"slack\"}]}]}','{\"thankYouMessage\":\"You\'re on the list! We\'ll reach out when beta access is available.\"}',1,'(NULL)','(NULL)','2026-03-20 07:03:12.000','2026-03-20 07:03:12.000'),('cmnh0s7hi001fxqalhol47vhg','My Registration Form','','custom','{\"fields\":[{\"id\":\"field_1775106624039\",\"type\":\"text\",\"label\":\"First Name\",\"required\":true,\"placeholder\":\"First name\"},{\"id\":\"field_1775106639577\",\"type\":\"text\",\"label\":\"Last Name\",\"required\":true,\"placeholder\":\"